import { Asset } from 'expo-asset';
import { File } from 'expo-file-system';
import * as THREE from 'three';

import meta from '@/assets/mannequin/mannequin.json';

// Mesh generated by scripts/mannequin/export.py; regions are baked per vertex (see dress.ts).
const SOURCES = { f: require('@/assets/mannequin/female.bin'), m: require('@/assets/mannequin/male.bin') };

export type BodyKey = 'f' | 'm';
type Landmarks = Record<string, number>;
export type Body = { n: number; H: number; pos: Float32Array; idx: Uint16Array; reg: Uint8Array; nrm: Float32Array; lm: Landmarks; skirt: number[][] };

const cache = new Map<BodyKey, Promise<Body>>();

export function loadBody(key: BodyKey): Promise<Body> {
  if (!cache.has(key)) cache.set(key, readBody(key));
  return cache.get(key)!;
}

async function readBody(key: BodyKey): Promise<Body> {
  const { n, t, lm, skirt } = meta[key];
  const [asset] = await Asset.loadAsync(SOURCES[key]);
  const buf = await new File(asset.localUri ?? asset.uri).arrayBuffer();
  const q = new Int16Array(buf, 0, n * 3);
  const pos = new Float32Array(n * 3);
  let H = 0;
  for (let j = 0; j < n * 3; j++) {
    pos[j] = q[j] / 16000;
    if (j % 3 === 1 && pos[j] > H) H = pos[j];
  }
  const idx = new Uint16Array(buf, n * 6, t * 3);
  const reg = new Uint8Array(buf, n * 6 + t * 6, n);
  const full = new THREE.BufferGeometry();
  full.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  full.setIndex(new THREE.BufferAttribute(idx, 1));
  full.computeVertexNormals();
  const nrm = full.getAttribute('normal').array as Float32Array;
  full.dispose();
  return { n, H, pos, idx, reg, nrm, lm, skirt };
}
